//! Replays `testdata/port/ingest/mail.json`, generated by the real Go
//! `TestPortIngestMailContract`: the IMAP mail poller (login, select, UID
//! cursor, UID search, envelope dedupe, body fetch, go-message attachment
//! reader, staging, enqueue, mark-seen/move, idempotency record, poll status,
//! Start/Close) against a scripted loopback IMAP server over TLS. Per scenario
//! the client commands the server saw, the server's final mailboxes, the store
//! tables, the staged files, the log output and every PollOnce result must
//! match what Go produced. No real account or network is used.
#![cfg(unix)]

use base64::Engine as _;
use regex::Regex;
use rusqlite::types::ValueRef;
use serde_json::{Value, json};
use std::path::Path;
use std::sync::{Arc, Mutex};
use symdesk_ingest::Store;
use symdesk_ingest::imap::{ImapClient, TlsImapClient};
use symdesk_ingest::mail::{ImapAccount, MailPoller, MailPollerOptions, account_id};

#[path = "support/imap_server.rs"]
mod imap_server;
use imap_server::{Server, client_config, parse_fail, parse_msg, parse_spec, snapshot};

/// The process environment (secrets, PATH) is global; scenarios run one at a time.
static ENV_LOCK: Mutex<()> = Mutex::new(());

fn fixture() -> Value {
    let f: Value = serde_json::from_slice(
        &std::fs::read(
            Path::new(env!("CARGO_MANIFEST_DIR")).join("../../testdata/port/ingest/mail.json"),
        )
        .unwrap(),
    )
    .unwrap();
    assert_eq!(f["schema_version"], 1);
    f
}

struct EnvGuard(Vec<(String, Option<std::ffi::OsString>)>);

impl EnvGuard {
    fn set(&mut self, k: &str, v: &str) {
        self.0.push((k.to_owned(), std::env::var_os(k)));
        // SAFETY: serialized by ENV_LOCK; no other thread reads these variables.
        unsafe { std::env::set_var(k, v) };
    }
}

impl Drop for EnvGuard {
    fn drop(&mut self) {
        for (k, v) in self.0.drain(..).rev() {
            // SAFETY: see `set`.
            unsafe {
                match v {
                    Some(v) => std::env::set_var(&k, v),
                    None => std::env::remove_var(&k),
                }
            }
        }
    }
}

fn mkdir_700(path: &Path) {
    use std::os::unix::fs::DirBuilderExt;
    std::fs::DirBuilder::new()
        .recursive(true)
        .mode(0o700)
        .create(path)
        .unwrap();
}

fn account_of(a: &Value, host: &str, port: i64) -> ImapAccount {
    let list = |k: &str| -> Vec<String> {
        a[k].as_str()
            .filter(|s| !s.is_empty())
            .map(|s| vec![s.to_owned()])
            .unwrap_or_default()
    };
    ImapAccount {
        host: host.to_owned(),
        port,
        username: a["username"].as_str().unwrap_or("").to_owned(),
        password_secret: a["password_secret"].as_str().unwrap_or("").to_owned(),
        folder: a["folder"].as_str().unwrap_or("").to_owned(),
        from: list("from"),
        subject: list("subject"),
        has_attachment: a["has_attachment"].as_bool().unwrap_or(false),
        action: a["action"].as_str().unwrap_or("").to_owned(),
        move_to: a["move_to"].as_str().unwrap_or("").to_owned(),
        archive_mail: false,
    }
}

fn apply_mutation(server: &Server, m: &Value, root: &Path) {
    let mut s = server.spec.lock().unwrap();
    let folder = m["folder"].as_str().unwrap_or("").to_owned();
    match m["op"].as_str().unwrap() {
        "append" => s
            .folders
            .entry(folder)
            .or_default()
            .messages
            .push(parse_msg(&m["msg"])),
        "uid-validity" => {
            s.folders.entry(folder).or_default().uid_validity = m["value"].as_u64().unwrap() as u32;
        }
        "set-flags" => {
            let uid = m["uid"].as_u64().unwrap() as u32;
            for msg in &mut s.folders.entry(folder).or_default().messages {
                if msg.uid == uid {
                    msg.flags = m["flags"]
                        .as_array()
                        .map(|a| a.iter().map(|f| f.as_str().unwrap().to_owned()).collect())
                        .unwrap_or_default();
                }
            }
        }
        "server-fail" => s.fail = parse_fail(&m["fail"]),
        "server-drop" => s.drop = m["drop"].as_str().unwrap_or("").to_owned(),
        "drop-files" => {
            let _ = std::fs::remove_dir_all(root.join("proc"));
            mkdir_700(&root.join("proc"));
        }
        other => panic!("unknown mutation {other}"),
    }
}

fn dump_table(
    db: &rusqlite::Connection,
    table: &str,
    root: &str,
    ts: &Regex,
    norm: &dyn Fn(&str) -> String,
) -> Vec<Value> {
    let _ = root;
    let mut stmt = db
        .prepare(&format!("SELECT * FROM {table} ORDER BY rowid"))
        .unwrap();
    let cols: Vec<String> = stmt
        .column_names()
        .iter()
        .map(|c| (*c).to_owned())
        .collect();
    let mut rows = stmt.query([]).unwrap();
    let mut out = Vec::new();
    while let Some(row) = rows.next().unwrap() {
        let mut map = serde_json::Map::new();
        for (i, c) in cols.iter().enumerate() {
            let mut v = match row.get_ref(i).unwrap() {
                ValueRef::Null => Value::Null,
                ValueRef::Integer(n) => json!(n),
                ValueRef::Real(f) => json!(f),
                ValueRef::Text(t) => {
                    json!(ts.replace_all(&norm(&String::from_utf8_lossy(t)), "<TS>"))
                }
                ValueRef::Blob(b) => json!(norm(&String::from_utf8_lossy(b))),
            };
            if c.ends_with("_at") && v.as_str().is_some_and(|s| !s.is_empty()) {
                v = json!("<TS>");
            }
            map.insert(c.clone(), v);
        }
        out.push(Value::Object(map));
    }
    out
}

fn snapshot_files(root: &Path, rel: &str) -> Vec<Value> {
    use std::os::unix::fs::PermissionsExt;
    fn walk(path: &Path, root: &Path, out: &mut Vec<Value>) {
        let meta = std::fs::symlink_metadata(path).unwrap();
        let r = path
            .strip_prefix(root)
            .unwrap()
            .to_string_lossy()
            .into_owned();
        let mode = format!("{:04o}", meta.permissions().mode() & 0o777);
        if meta.is_dir() {
            out.push(json!({"path": r, "type": "dir", "mode": mode}));
            let mut kids: Vec<_> = std::fs::read_dir(path)
                .unwrap()
                .map(|e| e.unwrap().path())
                .collect();
            kids.sort();
            for k in kids {
                walk(&k, root, out);
            }
        } else {
            let b64 =
                base64::engine::general_purpose::STANDARD.encode(std::fs::read(path).unwrap());
            let mut e = json!({"path": r, "type": "file", "mode": mode});
            if !b64.is_empty() {
                e["b64"] = json!(b64);
            }
            out.push(e);
        }
    }
    let base = root.join(rel);
    let mut out = Vec::new();
    if std::fs::symlink_metadata(&base).is_ok() {
        walk(&base, root, &mut out);
    }
    out.sort_by(|a, b| a["path"].as_str().cmp(&b["path"].as_str()));
    out
}

fn observe(sc: &Value, scratch: &Path) -> Value {
    let _lock = ENV_LOCK.lock().unwrap_or_else(|e| e.into_inner());
    let id = sc["id"].as_str().unwrap();
    let root = scratch.join(id);
    let _ = std::fs::remove_dir_all(&root);
    std::fs::create_dir_all(&root).unwrap();
    let root = std::fs::canonicalize(&root).unwrap();
    let mut env = EnvGuard(Vec::new());
    if let Some(vars) = sc["env"].as_object() {
        for (k, v) in vars {
            env.set(k, v.as_str().unwrap());
        }
    }
    if sc["tools"].as_object().is_some_and(|t| !t.is_empty())
        || sc["no_system_path"].as_bool() == Some(true)
    {
        use std::os::unix::fs::PermissionsExt;
        let tools = root.join("tools");
        std::fs::create_dir_all(&tools).unwrap();
        for (name, body) in sc["tools"].as_object().cloned().unwrap_or_default() {
            let path = tools.join(&name);
            std::fs::write(&path, body.as_str().unwrap()).unwrap();
            std::fs::set_permissions(&path, std::fs::Permissions::from_mode(0o700)).unwrap();
        }
        let p = if sc["no_system_path"].as_bool() == Some(true) {
            tools.to_string_lossy().into_owned()
        } else {
            format!("{}:/usr/bin:/bin", tools.display())
        };
        env.set("PATH", &p);
    }

    let mut server = Server::start(parse_spec(&sc["server"]));
    let addr = server.addr;
    let (host, port) = (addr.ip().to_string(), i64::from(addr.port()));
    if sc["no_listen"].as_bool() == Some(true) {
        server.close();
    }

    let norm_root = root.to_string_lossy().into_owned();
    let hostport = format!("{host}:{port}");
    let norm = move |s: &str| -> String {
        s.replace(&norm_root, "<ROOT>")
            .replace(&hostport, "127.0.0.1:<PORT>")
    };

    let store = Arc::new(Mutex::new(Store::open(&root.join("db/docs.db")).unwrap()));
    let acc = account_of(&sc["account"], &host, port);
    let mut accounts = vec![acc.clone()];
    for a in sc["accounts2"].as_array().into_iter().flatten() {
        accounts.push(account_of(a, &host, port));
    }
    let proc = match sc["processing_dir"].as_str().unwrap_or("") {
        "proc" => {
            mkdir_700(&root.join("proc"));
            root.join("proc").to_string_lossy().into_owned()
        }
        "file" => {
            {
                use std::os::unix::fs::OpenOptionsExt;
                let mut f = std::fs::OpenOptions::new()
                    .write(true)
                    .create_new(true)
                    .mode(0o600)
                    .open(root.join("proc"))
                    .unwrap();
                std::io::Write::write_all(&mut f, b"x").unwrap();
            }
            root.join("proc").to_string_lossy().into_owned()
        }
        _ => String::new(),
    };
    let mut poller = MailPoller::new(
        Arc::clone(&store),
        accounts.clone(),
        MailPollerOptions {
            interval: Some(std::time::Duration::from_secs(3600)),
            processing_dir: proc,
            failed_dir: String::new(),
        },
    )
    .unwrap();
    let config = client_config();
    poller.set_dial(Arc::new(move |addr, host| {
        let c = TlsImapClient::dial_tls(addr, host, Arc::clone(&config))?;
        Ok(Box::new(c) as Box<dyn ImapClient>)
    }));
    let logs: Arc<Mutex<String>> = Arc::new(Mutex::new(String::new()));
    {
        let logs = Arc::clone(&logs);
        poller.set_log(Arc::new(move |m| {
            let mut l = logs.lock().unwrap();
            l.push_str(&m);
            l.push('\n');
        }));
    }
    let hooks: Arc<Mutex<Vec<String>>> = Arc::new(Mutex::new(Vec::new()));
    let hook_mode = sc["hook"].as_str().unwrap_or("").to_owned();
    if hook_mode == "ok" || hook_mode == "fail" {
        let hooks = Arc::clone(&hooks);
        let norm = norm.clone();
        poller.set_enqueue(Arc::new(move |work_path, msg_id, correspondent| {
            hooks
                .lock()
                .unwrap()
                .push(format!("{}|{msg_id}|{correspondent}", norm(work_path)));
            if hook_mode == "fail" {
                return Err("hook refused".into());
            }
            Ok(())
        }));
    }

    let mut polls = Vec::new();
    let polls_n = sc["polls"].as_u64().unwrap_or(0).max(1) as usize;
    if sc["mode"].as_str() == Some("start") {
        poller.start().unwrap();
        let deadline = std::time::Instant::now() + std::time::Duration::from_secs(20);
        while std::time::Instant::now() < deadline {
            let done = accounts.iter().all(|a| {
                store
                    .lock()
                    .unwrap()
                    .get_mail_poll_status(&account_id(a))
                    .ok()
                    .flatten()
                    .is_some()
            });
            if done {
                break;
            }
            std::thread::sleep(std::time::Duration::from_millis(20));
        }
        poller.close();
    } else {
        for i in 0..polls_n {
            if i > 0
                && let Some(muts) = sc["between"].as_array().and_then(|b| b.get(i - 1))
            {
                for m in muts.as_array().into_iter().flatten() {
                    apply_mutation(&server, m, &root);
                }
            }
            let text = match poller.poll_once(&acc) {
                Ok(()) => String::new(),
                Err(e) => norm(&e.text),
            };
            polls.push(json!({"error": text}));
        }
    }
    drop(poller);
    if sc["no_listen"].as_bool() != Some(true) {
        server.close();
    }
    drop(store);

    let ts = Regex::new(r"\d{4}-\d\d-\d\dT\d\d:\d\d:\d\d(\.\d+)?(Z|[+-]\d\d:\d\d)").unwrap();
    let db = rusqlite::Connection::open_with_flags(
        root.join("db/docs.db"),
        rusqlite::OpenFlags::SQLITE_OPEN_READ_ONLY,
    )
    .unwrap();
    let mut tables = serde_json::Map::new();
    for t in [
        "documents",
        "jobs",
        "mail_messages",
        "mail_poll_cursor",
        "mail_poll_status",
    ] {
        let exists: i64 = db
            .query_row(
                "SELECT COUNT(*) FROM sqlite_master WHERE type='table' AND name=?",
                [t],
                |r| r.get(0),
            )
            .unwrap();
        if exists > 0 {
            tables.insert(
                t.to_owned(),
                Value::Array(dump_table(&db, t, "", &ts, &norm)),
            );
        }
    }
    let server_state = snapshot(&server.spec.lock().unwrap());
    let mut transcript: Vec<Vec<String>> = server.conns.lock().unwrap().clone();
    transcript.sort_by_key(|c| c.join("\n"));
    let mut log_lines: Vec<String> = logs
        .lock()
        .unwrap()
        .trim_end_matches('\n')
        .split('\n')
        .filter(|l| !l.is_empty())
        .map(&norm)
        .collect();
    log_lines.sort();
    let mut hook_lines = hooks.lock().unwrap().clone();
    hook_lines.sort();
    drop(env);
    json!({
        "polls": polls,
        "transcript": transcript,
        "server": server_state,
        "tables": tables,
        "files": snapshot_files(&root, "proc"),
        "logs": log_lines,
        "hooks": hook_lines,
    })
}

fn diff(path: &str, want: &Value, got: &Value, out: &mut Vec<String>) {
    match (want, got) {
        (Value::Object(a), Value::Object(b)) => {
            for key in a
                .keys()
                .chain(b.keys())
                .collect::<std::collections::BTreeSet<_>>()
            {
                diff(
                    &format!("{path}.{key}"),
                    a.get(key).unwrap_or(&Value::Null),
                    b.get(key).unwrap_or(&Value::Null),
                    out,
                );
            }
        }
        (Value::Array(a), Value::Array(b)) if a.len() == b.len() => {
            for (i, (x, y)) in a.iter().zip(b).enumerate() {
                diff(&format!("{path}[{i}]"), x, y, out);
            }
        }
        _ => {
            if want != got {
                let clip = |v: &Value| {
                    let s = v.to_string();
                    if s.len() > 300 {
                        format!("{}…", &s[..300])
                    } else {
                        s
                    }
                };
                out.push(format!("{path}: go {} rust {}", clip(want), clip(got)));
            }
        }
    }
}

fn compare(case: &Value, scratch: &Path) -> Vec<String> {
    let got = observe(&case["scenario"], scratch);
    let mut want = serde_json::Map::new();
    for key in [
        "polls",
        "transcript",
        "server",
        "tables",
        "files",
        "logs",
        "hooks",
    ] {
        want.insert(key.to_owned(), case[key].clone());
    }
    let mut diffs = Vec::new();
    diff("", &Value::Object(want), &got, &mut diffs);
    diffs
}

#[test]
fn mail_poller_matches_go() {
    let fx = fixture();
    let cases = fx["cases"].as_array().unwrap();
    assert!(cases.len() >= 60, "scenarios shrank: {}", cases.len());
    let scratch =
        Path::new(env!("CARGO_TARGET_TMPDIR")).join(format!("mail-{}", std::process::id()));
    std::fs::create_dir_all(&scratch).unwrap();
    let mut failures = Vec::new();
    for case in cases {
        let id = case["scenario"]["id"].as_str().unwrap();
        for d in compare(case, &scratch).into_iter().take(6) {
            failures.push(format!("{id}: {d}"));
        }
    }
    let _ = std::fs::remove_dir_all(&scratch);
    assert!(
        failures.is_empty(),
        "{} differences:\n{}",
        failures.len(),
        failures.join("\n")
    );
}

#[test]
fn mail_negative_controls_are_caught() {
    let fx = fixture();
    let cases = fx["cases"].as_array().unwrap();
    let scratch =
        Path::new(env!("CARGO_TARGET_TMPDIR")).join(format!("mail-neg-{}", std::process::id()));
    std::fs::create_dir_all(&scratch).unwrap();
    let case = cases
        .iter()
        .find(|c| c["scenario"]["id"] == "move-action")
        .unwrap();
    assert!(compare(case, &scratch).is_empty());
    for mutate in [
        |c: &mut Value| c["transcript"][0][2] = json!("UID SEARCH UID 2:*"),
        |c: &mut Value| c["files"][1]["b64"] = json!("AAAA"),
        |c: &mut Value| c["tables"]["mail_messages"][0]["message_id"] = json!("other"),
        |c: &mut Value| c["server"]["Archive"]["messages"] = json!([]),
        |c: &mut Value| c["logs"] = json!([]),
        |c: &mut Value| c["polls"][0]["error"] = json!("boom"),
    ] {
        let mut tampered = case.clone();
        mutate(&mut tampered);
        assert!(
            !compare(&tampered, &scratch).is_empty(),
            "tampering went unnoticed"
        );
    }
    let _ = std::fs::remove_dir_all(&scratch);
}

#[test]
fn mail_scenarios_exercise_the_interesting_paths() {
    let fx = fixture();
    let cases = fx["cases"].as_array().unwrap();
    let files: usize = cases
        .iter()
        .map(|c| {
            c["files"]
                .as_array()
                .unwrap()
                .iter()
                .filter(|f| f["type"] == "file")
                .count()
        })
        .sum();
    let errors: usize = cases
        .iter()
        .flat_map(|c| c["polls"].as_array().unwrap())
        .filter(|p| p["error"] != "")
        .count();
    assert!(
        files >= 40 && errors >= 14,
        "oracle too thin: {files} files, {errors} errors"
    );
}
